// ===========================================================================
//  BẢNG QUYẾT ĐỊNH 7 CÂU - nhập mã định mua, hệ thống tự chấm 4 câu định lượng,
//  nhắc anh tự trả lời 3 câu định tính. Trả lời được TRỌN 7 -> mới cân nhắc vào.
// ===========================================================================
const NAV     = 5000000;  // ĐỒNG
const TICKER  = 'BID';
const ENTRY   = 42.0;     // nghìn đồng
const STOP    = 39.0;
const TARGET  = 46.0;
const RISK_PCT = 1.5;
// ===========================================================================

const to = Math.floor(Date.now() / 1000), from = to - 60 * 60 * 24 * 60;
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const hBar = { 'User-Agent': UA, 'Accept': '*/*' };
const hFin = { 'User-Agent': UA, 'Accept': 'application/json', 'Referer': 'https://dstock.vndirect.com.vn/' };

const getPE = async () => {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/ratios?q=code:' + TICKER + '~itemCode:51006,1000043&sort=reportDate:desc&size=10', headers: hFin, json: false, timeout: 15000 });
    let p; try { p = typeof res === 'string' ? JSON.parse(res) : res; } catch (e) { p = null; }
    const m = {}; for (const d of ((p && p.data) || [])) { if (!(d.ratioCode in m)) m[d.ratioCode] = d.value; }
    return { pe: m['PRICE_TO_EARNINGS'], pe5: m['PRICE_TO_EARNINGS_AVG_CR_5Y'] };
  } catch (e) { return {}; }
};
const getFlow = async () => {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/foreigns?q=code:' + TICKER + '&size=5&sort=tradingDate:desc', headers: hFin, json: true, timeout: 15000 });
    const nets = ((res && res.data) || []).map(x => (x.netVal || 0) / 1e9);
    if (!nets.length) return { txt: 'không lấy được' };
    const dir = nets[0] > 1 ? 1 : nets[0] < -1 ? -1 : 0;
    let streak = 0; for (const v of nets) { const s = v > 1 ? 1 : v < -1 ? -1 : 0; if (s === dir && dir !== 0) streak++; else break; }
    const tot5 = nets.reduce((a, b) => a + b, 0);
    return { txt: 'phiên gần nhất ' + nets[0].toFixed(1) + ' tỷ' + (streak >= 2 ? ' · ' + (dir > 0 ? 'GOM' : 'XẢ') + ' ' + streak + ' phiên' : '') + ' · tổng 5 phiên ' + tot5.toFixed(1) + ' tỷ', dir, streak };
  } catch (e) { return { txt: 'lỗi' }; }
};

const pe = await getPE();
const fl = await getFlow();

// Câu 2: định giá
let q2 = '_thiếu dữ liệu P/E_';
if (pe.pe > 0 && pe.pe5 > 0) {
  const r = pe.pe / pe.pe5;
  const tag = r <= 0.85 ? '🟢 RẺ so lịch sử' : r >= 1.15 ? '🔴 ĐẮT so lịch sử' : '🟡 quanh trung bình';
  q2 = 'P/E ' + pe.pe.toFixed(1) + ' vs TB5N ' + pe.pe5.toFixed(1) + ' → ' + tag;
} else if (pe.pe > 0) q2 = 'P/E ' + pe.pe.toFixed(1) + ' _(thiếu TB lịch sử)_';

// Câu 6: sizing & R:R
const entryD = ENTRY * 1000, riskBudget = NAV * RISK_PCT / 100, riskPerShare = (ENTRY - STOP) * 1000, lotCost = entryD * 100;
const sharesByRisk = STOP < ENTRY ? Math.floor(riskBudget / riskPerShare / 100) * 100 : 0;
const rr = TARGET > ENTRY && STOP < ENTRY ? (TARGET - ENTRY) / (ENTRY - STOP) : null;
let q6;
if (!(STOP < ENTRY)) q6 = '🔴 cắt lỗ phải < giá vào';
else if (sharesByRisk >= 100) q6 = 'mua ' + sharesByRisk + ' cp theo quy tắc ' + RISK_PCT + '% · R:R ' + (rr ? rr.toFixed(2) : 'n/a') + (rr && rr < 2 ? ' ⚠️mỏng' : '');
else q6 = (lotCost <= NAV ? '⚠️ chỉ đủ ~1 lô (' + (lotCost / NAV * 100).toFixed(0) + '% NAV → tập trung cao)' : '🔴 NAV không đủ 1 lô') + ' · R:R ' + (rr ? rr.toFixed(2) : 'n/a') + (rr && rr < 2 ? ' ⚠️mỏng' : '');

const flags = [];
if (/🔴/.test(q2)) flags.push('định giá đắt so lịch sử');
if (fl.dir === -1 && fl.streak >= 3) flags.push('khối ngoại đang xả');
if (rr && rr < 2) flags.push('R:R < 2 (mỏng)');
if (sharesByRisk < 100 && lotCost <= NAV) flags.push('vị thế tập trung quá cao');

const now = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
const L = [];
L.push('🧭 *BẢNG QUYẾT ĐỊNH — ' + TICKER + '*');
L.push('_Vào ' + Math.round(ENTRY * 1000).toLocaleString('vi-VN') + 'đ · Cắt lỗ ' + Math.round(STOP * 1000).toLocaleString('vi-VN') + 'đ · Mục tiêu ' + Math.round(TARGET * 1000).toLocaleString('vi-VN') + 'đ · NAV ' + (NAV / 1e6).toFixed(1) + ' triệu_');
L.push('_' + now + '_');
L.push('');
L.push('*① HIỂU DN?* _(anh tự trả lời)_ — Có hiểu ' + TICKER + ' kiếm tiền thế nào, vì sao tồn tại?');
L.push('*② RẺ/ĐẮT?* ✅tự động — ' + q2);
L.push('*③ LUẬN ĐIỂM & ĐIỀU GÌ LÀM SAI?* _(anh tự viết — dùng Sổ luận điểm)_');
L.push('*④ BỐI CẢNH?* ✅tự động — Khối ngoại: ' + fl.txt);
L.push('   _(+ anh tự đánh giá: ngành thuận/nghịch? đám đông đã pricing gì?)_');
L.push('*⑤ THỜI ĐIỂM?* _(anh tự trả lời)_ — Có chất xúc tác, hay đang bắt dao rơi?');
L.push('*⑥ KÍCH THƯỚC & R:R?* ✅tự động — ' + q6);
L.push('*⑦ THOÁT?* ✅tự động — Cắt lỗ ' + Math.round(STOP * 1000).toLocaleString('vi-VN') + 'đ ✓ · Mục tiêu ' + Math.round(TARGET * 1000).toLocaleString('vi-VN') + 'đ ✓');
L.push('');
if (flags.length) L.push('⚠️ *Cờ định lượng:* ' + flags.join(' · '));
L.push('📝 *Anh PHẢI tự trả lời câu ①③⑤* trước khi quyết định.');
L.push('');
L.push('> *Quy tắc thép:* không trả lời được TRỌN 7 câu → ĐỨNG NGOÀI. Tiền mặt là một vị thế.');
L.push('_Không phải khuyến nghị mua/bán._');

return [{ json: { message: L.join('\n') } }];
